CREATE TABLE planet_properties_earth_units (
    planet_ref INTEGER PRIMARY KEY,
    mass_earth_units NUMERIC(10, 4),
    radius_earth_units NUMERIC(10, 4),
    FOREIGN KEY (planet_ref) REFERENCES planets(planetref)
);

CREATE TABLE high_precision_params (
    planet_ref INTEGER PRIMARY KEY REFERENCES planets(planetref),
    has_hp_mass BOOLEAN,
    has_hp_radius BOOLEAN,
    has_hp_period BOOLEAN
);

CREATE TABLE star_classifications (
    stellar_ref INTEGER PRIMARY KEY,
    class_name VARCHAR(20),
    FOREIGN KEY (stellar_ref) REFERENCES stars(stellarref)
);

CREATE TABLE planet_types (
    planet_ref INTEGER PRIMARY KEY REFERENCES planets(planetref),
    type_name VARCHAR(50)
);

CREATE TABLE system_period_ratios (
    host_link INTEGER,
    inner_planet_period NUMERIC,
    outer_planet_period NUMERIC,
    period_ratio NUMERIC
);

SELECT COUNT(*) FROM (
    SELECT host_link 
    FROM system_period_ratios 
    GROUP BY host_link 
    HAVING MAX(period_ratio) < 3
) AS compact_systems;

CREATE OR REPLACE FUNCTION get_remaining_maintenance_budget(total_budget NUMERIC DEFAULT 25000) RETURNS NUMERIC AS $$
DECLARE
    spent_budget NUMERIC;
    remaining_budget NUMERIC;
BEGIN
    SELECT COALESCE(SUM(treatment_cost), 0) INTO spent_budget FROM "MV_Prioritized_Maintenance_Plan";
    remaining_budget := total_budget - spent_budget;
    RETURN remaining_budget;
END;
$$ LANGUAGE plpgsql;

