CREATE OR REPLACE FUNCTION calculate_ted(shipment_reckey TEXT)
RETURNS INTEGER AS $$
DECLARE
    total_excursion_duration INTEGER := 0;
    env_data JSONB;
BEGIN
    SELECT env_metrics INTO env_data
    FROM environmentalmonitoring 
    WHERE reckeylink = shipment_reckey;
    IF env_data IS NOT NULL AND env_data->'temperature'->>'excursion_duration_min' IS NOT NULL THEN
        total_excursion_duration := (env_data->'temperature'->>'excursion_duration_min')::INTEGER;
    END IF;
    RETURN COALESCE(total_excursion_duration, 0);
END;
$$ LANGUAGE plpgsql;

