    env_data JSONB;
BEGIN
    SELECT env_metrics INTO env_data
    FROM environmentalmonitoring 
    WHERE reckeylink = shipment_reckey;
    IF env_data IS NOT NULL AND env_data->'temperature'->>'excursion_duration_min' IS NOT NULL THEN
