    END IF;
    RETURN COALESCE(total_excursion_duration, 0);
END;
$$ LANGUAGE plpgsql;

SELECT 
    s.reckey AS shipment_id,
    calculate_ted(s.reckey) AS ted
FROM shipments s
LEFT JOIN environmentalmonitoring em
    ON s.reckey = em.reckeylink
ORDER BY ted DESC
LIMIT 5;

