CREATE OR REPLACE FUNCTION assess_quality_risk_zone()
RETURNS TRIGGER AS $$
DECLARE
    excursion_duration INTEGER;
    excursion_count INTEGER;
    time_in_range_pct NUMERIC;
    risk_zone TEXT;
BEGIN
    excursion_duration := COALESCE((NEW.env_metrics->'temperature'->>'excursion_duration_min')::INTEGER, 0);
    excursion_count := COALESCE((NEW.env_metrics->'temperature'->>'excursion_count')::INTEGER, 0);

    time_in_range_pct := CASE 
        WHEN excursion_duration = 0 THEN 100.0
        ELSE ROUND(((4320 - excursion_duration)::NUMERIC / 4320.0) * 100, 2)
    END;

    IF time_in_range_pct > 98 AND excursion_duration <= 30 THEN
        risk_zone := 'GREEN';
    ELSIF (time_in_range_pct >= 95 AND time_in_range_pct <= 98) OR (excursion_duration BETWEEN 31 AND 60) THEN
        risk_zone := 'YELLOW';
    ELSIF time_in_range_pct < 95 OR excursion_duration > 60 THEN
        risk_zone := 'RED';
    ELSE
        risk_zone := 'UNKNOWN';
    END IF;

    NEW.env_metrics := NEW.env_metrics || jsonb_build_object(
        'quality_risk_zone', risk_zone,
        'time_in_range_pct', time_in_range_pct
    );

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

SELECT
    ROUND(
        100.0 * COUNT(*) FILTER (
            WHERE (env_metrics->>'quality_risk_zone') = 'RED'
        ) / NULLIF(COUNT(*), 0),
        2
    ) AS red_zone_pct
FROM environmentalmonitoring;

DO $$
DECLARE
    rec RECORD;
    tier1_count INTEGER := 0;
    batch_cursor CURSOR FOR 
        SELECT pb.batchtag, p.prodcode, p.prodlabel, pb.valusd, pb.tempsense
        FROM productbatches pb
        INNER JOIN products p ON pb.prodlink = p.prodcode
        WHERE LOWER(TRIM(pb.tempsense)) = 'high' 
        AND REPLACE(REPLACE(pb.valusd, '$', ''), ',', '')::NUMERIC > 100000;
BEGIN
    CREATE TEMP TABLE IF NOT EXISTS tier1_products (
        batchtag TEXT,
        prodcode TEXT,
        prodlabel TEXT,
        value_usd NUMERIC,
        flagged_ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );

    FOR rec IN batch_cursor LOOP
        BEGIN
            INSERT INTO tier1_products (batchtag, prodcode, prodlabel, value_usd)
            VALUES (
                rec.batchtag, 
                rec.prodcode, 
                rec.prodlabel,
                REPLACE(REPLACE(rec.valusd, '$', ''), ',', '')::NUMERIC
            );

            tier1_count := tier1_count + 1;

            RAISE NOTICE 'Flagged Tier 1 product: % (Batch: %, Value: %)', 
                rec.prodlabel, rec.batchtag, rec.valusd;

        EXCEPTION
            WHEN OTHERS THEN
                RAISE NOTICE 'Error processing batch %: %', rec.batchtag, SQLERRM;
        END;
    END LOOP;

    RAISE NOTICE 'Batch processing complete. Total Tier 1 products identified: %', tier1_count;

    IF tier1_count > 0 THEN
        UPDATE productbatches 
        SET valusd = valusd || ' [TIER1]'
        WHERE batchtag IN (SELECT batchtag FROM tier1_products)
        AND valusd NOT LIKE '%[TIER1]%';
    END IF;
END $$;

SELECT 
  ROUND(
    100.0 * COUNT(*) FILTER (WHERE valusd LIKE '%[TIER1]%') / NULLIF(COUNT(*), 0), 
    2
  ) AS tier1_percentage
FROM productbatches;

